15		"github.com/aoagents/agent-orchestrator/backend/internal/httpd/envelope"
16		"github.com/aoagents/agent-orchestrator/backend/internal/ports"
17		sessionsvc "github.com/aoagents/agent-orchestrator/backend/internal/service/session"
18		sessionmanager "github.com/aoagents/agent-orchestrator/backend/internal/session_manager"
19	)
20	
21	const (
22		maxPromptLen  = 4096
23		maxMessageLen = 4096
24	)
25	
26	// SessionService is the controller-facing session service contract.
27	type SessionService interface {
28		List(ctx context.Context, filter sessionsvc.ListFilter) ([]domain.Session, error)
29		Spawn(ctx context.Context, cfg ports.SpawnConfig) (domain.Session, error)
30		Get(ctx context.Context, id domain.SessionID) (domain.Session, error)
31		Restore(ctx context.Context, id domain.SessionID) (domain.Session, error)
32		Kill(ctx context.Context, id domain.SessionID) (bool, error)
33		Send(ctx context.Context, id domain.SessionID, message string) error
34	}
35	
36	// SessionsController owns the session routes. Nil keeps routes registered but
37	// returns OpenAPI-backed 501s.
38	type SessionsController struct {
39		Svc SessionService
40	}
41	
42	// Register mounts the session routes on the supplied router.
43	func (c *SessionsController) Register(r chi.Router) {
44		r.Get("/sessions", c.list)
45		r.Post("/sessions", c.spawn)
46		r.Get("/sessions/{sessionId}", c.get)
47		r.Patch("/sessions/{sessionId}", c.rename)
48		r.Post("/sessions/{sessionId}/restore", c.restore)
49		r.Post("/sessions/{sessionId}/kill", c.kill)
50		r.Post("/sessions/{sessionId}/send", c.send)
51		r.Post("/orchestrators", c.spawnOrchestrator)
